create database Customer_Behaviour;
use Customer_Behaviour;
show tables;
select * from customer_data limit 20;
 
-- Q1. What is the total revenue generated by male vs. female customers?
select gender,sum(purchase_amount) as Revenue
from customer_data
group by gender;

-- Q2. Which customers used a discount but still spent more than the average purchase amount?
select customer_id,purchase_amount
from customer_data
where discount_applied='Yes' and purchase_amount >=(select avg(purchase_amount) from customer_data);

-- Q3. Which are the top 5 products with the highest average review rating?
select item_purchased as Item,round(avg(review_rating),2) as Review_Rating
from customer_data
group by item_purchased
order by avg(review_rating) desc
limit 5;

-- Q4. Compare the average Purchase Amounts between Standard and Express Shipping.
select shipping_type,avg(purchase_amount)
from customer_data
group by shipping_type
having shipping_type in ("Express","standard");

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.
select subscription_status,
count(customer_id) as Customers,
sum(purchase_amount) as Total_Spent,
round(avg(purchase_amount),2) as Average_Spent
from customer_data
group by subscription_status
order by Average_spent,Total_Spent desc;

-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?
select item_purchased,round(sum(case when discount_applied="Yes" then 1 else 0 end)/count(*)*100,2) as discount_rate
from customer_data
group by item_purchased
order by discount_rate desc
limit 5;

-- Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of customers in each segment.
with customer_segment as (select customer_id,previous_purchases,case when previous_purchases = 1 then "New" 
when previous_purchases between 2 and 10 then "Returning"
when previous_purchases >10 then "Loyal" end as Segment
from customer_data)
select Segment,count(*)
from customer_segment
group by segment;

